import sys
from collections import defaultdict

def solve(n, b, p):
    graph = defaultdict(list)
    for i in range(n):
        if b[i] != i + 1:
            graph[b[i] - 1].append(i)

    pos = {x: i for i, x in enumerate(p)}

    def dfs(node, current_dist):
        if node != -1 and dist[node] != -1:
            return False
        dist[node] = current_dist
        for child in graph[node]:
            if not dfs(child, current_dist + 1):
                return False
        return True

    dist = [-1] * n
    for i in range(n):
        if b[i] == i + 1:
            if not dfs(i, 0):
                return [-1]

    weights = [0] * n
    used_weights = set()

    for v in p:
        if b[v - 1] != v:
            parent_dist = dist[b[v] - 2]
            child_dist = dist[v - 1]
            needed_weight = child_dist - parent_dist
            for weight in range(1, 10**9 + 1):
                if weight not in used_weights and weight >= needed_weight:
                    weights[v - 1] = weight
                    used_weights.add(weight)
                    break
            else:
                return [-1]

    return weights

